SELECT t0.QUANTITY AS "Quantity" FROM trading.contractualposition AS t0 LEFT OUTER JOIN ref_data.account_master AS t2 ON (t2.ID = t0.ACCOUNT_ID AND t2.in_z <= '2024-09-01 12:00:00' AND (t2.out_z > '2024-09-01 12:00:00' OR t2.out_z IS NULL)) LEFT OUTER JOIN ref_data.desk AS t3 ON (t3.ID = t2.DESK_ID) LEFT OUTER JOIN (SELECT DISTINCT t4.DESK_ID AS "DESK_ID" FROM ref_data.account_master AS t4 WHERE t4.in_z <= '2024-09-01 12:00:00' AND (t4.out_z > '2024-09-01 12:00:00' OR t4.out_z IS NULL)) AS t1 ON (t3.ID = t1.DESK_ID) WHERE t1.DESK_ID IS NOT NULL AND t0.in_z <= '2024-09-01 12:00:00' AND (t0.out_z > '2024-09-01 12:00:00' OR t0.out_z IS NULL) ORDER BY t0.QUANTITY ASC NULLS FIRST
